-- V7: council budget (reference: JAMUNA BUDGET.xlsx).
-- Amounts are planned allocations from the council sheet, not actual spend.

CREATE TABLE budget_setting (
    id              INTEGER PRIMARY KEY CHECK (id = 1),
    title           VARCHAR(160) NOT NULL,
    subtitle        VARCHAR(160),
    per_head_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    resident_count  INTEGER NOT NULL DEFAULT 0,
    updated_at      TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by      VARCHAR(64) NOT NULL DEFAULT 'office'
);

CREATE TABLE budget_portfolio (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code             VARCHAR(32) NOT NULL UNIQUE,
    name             VARCHAR(160) NOT NULL,
    allocated_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    display_order    INTEGER NOT NULL DEFAULT 0,
    notes            VARCHAR(1000)
);

CREATE TABLE budget_item (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    portfolio_id   BIGINT NOT NULL REFERENCES budget_portfolio(id) ON DELETE CASCADE,
    item_name      VARCHAR(240) NOT NULL,
    category       VARCHAR(80),
    quantity       VARCHAR(80),
    unit_cost      NUMERIC(12,2),
    planned_cost   NUMERIC(12,2) NOT NULL DEFAULT 0,
    remarks        VARCHAR(1000),
    link_url       VARCHAR(512),
    display_order  INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX idx_budget_portfolio_order ON budget_portfolio (display_order);
CREATE INDEX idx_budget_item_portfolio ON budget_item (portfolio_id, display_order);



